INSERT INTO temp_import_pages VALUES ('{"pageId": "c0160000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "sourceShowsPrintedPageLabel": true, "printedPageLabel": "16", "printedPageNumber": 16, "pdfPageNumber": 399, "sequenceIndex": 6, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true, "provenanceNotes": "Canonical transcription checked against the rendered secondary scan; master PDF page mapping retained. Fine vocalisation is preserved where clearly legible; no unresolved Arabic word or letter remains. English OCR correction and Arabic/translation-pair classification pass compared against the rendered source scan; raw OCR retained unchanged."}, "structuralNodes": [{"id": "a6000000-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "PART I", "sourceIdentifier": "I", "title": "IMPORTANCE OF SALAAT", "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "a6100000-0000-4000-8000-000000000001", "parentId": "a6000000-0000-4000-8000-000000000001", "nodeType": "chapter", "sourceLabel": "CHAPTER I", "sourceIdentifier": "I", "title": "THE REWARDS OF SALAAT", "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "a6200000-0000-4000-8000-000000000005", "parentId": "a6100000-0000-4000-8000-000000000001", "nodeType": "hadith", "sourceLabel": "Hadith.—IV(b)", "sourceIdentifier": "IV(b)", "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}], "blocks": [{"id": "d0160000-0000-4000-8000-000000000001", "structuralNodeId": "a6200000-0000-4000-8000-000000000005", "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "\"The likeness of five times daily salaat is as the likeness of a deep brook running in front of the door of a person who bathes therein five times a day.\" Running water is generally free from dirt, and the deeper it runs the cleaner and purer it is. A bath in such water surely removes dirt from the body and makes it clean. Salaat offered with due regard for its essentials likewise cleanses the soul of all sins. There are several ahaadith of the same meaning, though. with slight variations in expression, narrated by different companions of the Prophet (Sallallaho alaihe wasallam). Hadhrat Abu Sa''eed Khudri (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying: ''Each of the five salaats expiates the sins committed since the salaat preceding it. To explain. let us take the case of a person working in a factory. His job is such that his body gets covered with dust. But there are five streams of running water in between the factory and his house and, on his return from the job, he takes a bath in each stream. The effect of five times daily salaat is quite similar. Any sins of omission and commission between two salaats are.forgiven on account of ''istighfaar and taubah in each salaat.'' The Prophet (Sallallaho alaihe wasallam) through such parables, aims at impressing that salaat has the wonderful power of removing the sins. If we fail to avail of Allah''s mercy, surely we ourselves are the losers. To err is human. We are -likely to commit innumerable acts of displeasing Allah and deserve thereby. His wrath and punishment, but look how relenting our dear Allah is! He has most graciously shown us the way to earn His mercy and forgiveness. It is a great pity if we do not avail of this great favour. Our Allah is always eager to show us His mercy on very small younds. It is said in a hadith, that if a person goes to bed with the intention of getting up for Tahajjud and perchance does not wake up, he receives the full reward for Tahajjud, although he has been enjoying his sleep at the time of Tahajjud. How boundless is the grace of Allah and what a tremendous loss and deprivation if we do not receive blessings from such a Giver.", "rawOcrText": "16 Virtues of Salaat \"The likeness of five times daily salaat is as the like- ness of a deep brook running in front of the door of a person who bathes therein five times a day.\" Running water is generally free from dirt, and the deeper it runs the cleaner and purer it is. A bath in such water surely removes dirt from the body and makes it clean. Salaat offered with due regard for its essentials like- wise cleanses the soul of all sins. There are several ahaa- dith of the same meaning, though. with slight variations in expression, narrated by different companions of the Prophet (Sallallaho alaihe wasallam). Hadhrat Abu Sa''eed Khudri (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alame wasallam) saying: ''Each of the five salaats expiates the sins committed since the salaat preceding it. To explain. let us take the case of a person working in a factory. His job is such that his body gets covered with dust. But there are five streams of running water in between the factory and his house and, on his return from the job, he takes a bath in each stream. The effect of five times daily salaat is quite similar. Any sins of omission and com- mission between two salaats are .forgiven on account of ''istighfaar and taubah in each salaat.'' The Prophet (Sallallaho alaihe wasallam) through such parables, aims at impressing that salaat has the wonderful power of removing the sins. If we fail to avail of Allah''s mercy, surely we ourselves are the losers. To err is human. We are -likely to commit innumerable acts of displeasing Allah and deserve thereby. His wrath and punishment, but look how relenting our dear Allah is! He has most graciously shown us the way to earn His mercy and forgiveness. It is a great pity if we do not avail of this great favour. Our Allah is always eager to show us His mercy on very small younds. It is said in a hadith, that if a person goes to bed with the intention of getting up for Ta- hajjud and perchance does not wake up, he receives the full reward for Tahajjud, although he has been enjoying his sleep at the time of Tahajjud. How boundless is the grace of Allah and what a tremendous loss and deprivation if we do not receive blessings from such a Giver.", "ttsEligible": true, "verificationStatus": "in_review"}], "pageNumber": 16}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "c0170000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "sourceShowsPrintedPageLabel": true, "printedPageLabel": "17", "printedPageNumber": 17, "pdfPageNumber": 400, "sequenceIndex": 7, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true, "provenanceNotes": "Canonical transcription checked against the rendered secondary scan; master PDF page mapping retained. Fine vocalisation is preserved where clearly legible; no unresolved Arabic word or letter remains. English OCR correction and Arabic/translation-pair classification pass compared against the rendered source scan; raw OCR retained unchanged."}, "structuralNodes": [{"id": "a6000000-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "PART I", "sourceIdentifier": "I", "title": "IMPORTANCE OF SALAAT", "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "a6100000-0000-4000-8000-000000000001", "parentId": "a6000000-0000-4000-8000-000000000001", "nodeType": "chapter", "sourceLabel": "CHAPTER I", "sourceIdentifier": "I", "title": "THE REWARDS OF SALAAT", "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "a6200000-0000-4000-8000-000000000006", "parentId": "a6100000-0000-4000-8000-000000000001", "nodeType": "hadith", "sourceLabel": "Hadith.—V", "sourceIdentifier": "V", "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}], "blocks": [{"id": "d0170000-0000-4000-8000-000000000001", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 0, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith.—V", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0170000-0000-4000-8000-000000000002", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 1, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عَنْ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ كَانَ رَسُولُ اللَّهِ ﷺ إِذَا حَزَبَهُ أَمْرٌ فَزِعَ إِلَى الصَّلَاةِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0170000-0000-4000-8000-000000000003", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "أخرجه أحمد وأبو داود وابن جرير كذا في الدر المنثور", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0170000-0000-4000-8000-000000000004", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "\"Hadhrat Huzaifah (Radhiyallaho anho) says that, whenever the Prophet (Sallallaho alaihe wasallam) happened to face any difficulty, he would at once resort to.salaat. \" Salaat is a great blessing of Allah. To resort to salaat at the time of worry is to hasten towards His mercy, and when Allah''s mercy comes to rescue, there can remain no trace of any worry. There are many traditions concerning this practice of the Holy Prophet (Sallallaho alaihe wasallam). Similar was the practice of his companions, who followed him in the minutest detail: Abu Darda (Radhiyallaho anho) says: -\"Whenever a strong wind blew, the Prophet (Sallallaho alaihe wasallam) would immediately enter the musjid and would not leave until the wind had subsided. Similarly, at the time of a solar or lunar eclipse, the Prophet (Sallallaho alaihe wasallam) would at once start offering salaat. Hadhrat Suhaib (Radhiyallaho anho) was informed by the Prophet (Sallallaho alaihe wasallam) that all the previous Apostles of Allah (peace be upon them) also used to resort to salaat in all adversities. Hadhrat Ibno Abbas (Radhiyallaho anho) was once on journey. On his way he got the news of the death of his son. He got down from his camel and offered two rakaats of salaat, praying in Tashahhud for a long time. He then recited ''Innaa lillaahi wa innaallaihi raaji-oon'' and said, \"I have done what Allah has ordered us to do in His Holy Book i.e.: \" Seek Allah''s help with patience and salaat\" (II: 45). Another similar story is narrated about him. He was on a journey when he received the news about the death of his brother Quthum. He descended from his camel by the roadside, and performed two rakaats of salaat and kept praying in Tashahhud for a long time. After finishing his salaat, he", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}], "pageNumber": 17}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "c0180000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "sourceShowsPrintedPageLabel": true, "printedPageLabel": "18", "printedPageNumber": 18, "pdfPageNumber": 401, "sequenceIndex": 8, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true, "provenanceNotes": "Canonical transcription checked against the rendered secondary scan; master PDF page mapping retained. Fine vocalisation is preserved where clearly legible; no unresolved Arabic word or letter remains. English OCR correction and Arabic/translation-pair classification pass compared against the rendered source scan; raw OCR retained unchanged."}, "structuralNodes": [{"id": "a6000000-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "PART I", "sourceIdentifier": "I", "title": "IMPORTANCE OF SALAAT", "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "a6100000-0000-4000-8000-000000000001", "parentId": "a6000000-0000-4000-8000-000000000001", "nodeType": "chapter", "sourceLabel": "CHAPTER I", "sourceIdentifier": "I", "title": "THE REWARDS OF SALAAT", "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "a6200000-0000-4000-8000-000000000006", "parentId": "a6100000-0000-4000-8000-000000000001", "nodeType": "hadith", "sourceLabel": "Hadith.—V", "sourceIdentifier": "V", "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}], "blocks": [{"id": "d0180000-0000-4000-8000-000000000001", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "rode his camel reciting the following verse of the Holy Qur''an:", "rawOcrText": "18 Virtues of Salaat rode his camel reciting the following verse of the Holy Qur''an: \"Seek Allah''s help with patience and salaat, and truly it is indeed hard except to the humble minded.\" (11:45). There is yet another story about him. On hearing of the death of a wife of the Holy Prophet (Sallallaho alaihe wa- sallam), he fell down prostrate. When somebody asked him the reason he said, \"Our dear Prophet (SaHal-laho alaihe wasallam) had enjoined on us to prostrate (in salaat) when- ever a calamity were to béfall What calamity can be g•eater than the death of the Ummul-üo''mineen?\" When Hadhrat Ubaada (Radhiyallaho anho) was about to breathe his last, he said to the people around him, \"1_ prohibit one and all from crying over me. When my \"ul departs, I ask every one to perform wudhu, observing all its essentials, and to go to the musjid and pray for my forgive- ness, because our Gracious Allah has enjoined on us to \"Seek help with patience and salaat.\" After that, lay me down in the pit of my grave.\" Hadhrat Nadhr (Radhiyallaho anho) narrates, \"Once it became very dark during the day in Madina. I hurriedly went to Hadhrat Anas (Radhiyallaho anho) to know if he had ever experienced similar conditions during the life- time of the Holy Prophet (Sallallaho alaibe wasallam). He said to me, During those blessed days, whenever the. wind blew strong, we would hurry to the musjid lest it should be the approach of the Last Day. \" Hadhrat Abdullah bin Salaam (Radhiyallaho anho) narrates that whenever the members of the Prophet''s family were hardpressed in any . way, the Prophet (Sallallaho alaihe wasallam) would enjoin upon them to say salaat, and would recite the following verse of the Holy Qur''an:", "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0180000-0000-4000-8000-000000000002", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 1, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَاسْتَعِينُوا بِالصَّبْرِ وَالصَّلَاةِ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى الْخَاشِعِينَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0180000-0000-4000-8000-000000000003", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 2, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "“Seek Allah''s help with patience and salaat, and truly it is indeed hard except to the humble minded.” (II: 45).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0180000-0000-4000-8000-000000000006", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "There is yet another story about him. On hearing of the death of a wife of the Holy Prophet (Sallallaho alaihe wasallam), he fell down prostrate. When somebody asked him the reason he said, “Our dear Prophet (Sallallaho alaihe wasallam) had enjoined on us to prostrate (in salaat) whenever a calamity were to befall us. What calamity can be greater than the death of the Ummul-Mo’mineen?” When Hadhrat Ubaada (Radhiyallaho anho) was about to breathe his last, he said to the people around him, “I prohibit one and all from crying over me. When my soul departs, I ask every one to perform wudhu, observing all its essentials, and to go to the musjid and pray for my forgiveness, because our Gracious Allah has enjoined on us to “Seek help with patience and salaat.” After that, lay me down in the pit of my grave.” Hadhrat Nadhr (Radhiyallaho anho) narrates, “Once it became very dark during the day in Madina. I hurriedly went to Hadhrat Anas (Radhiyallaho anho) to know if he had ever experienced similar conditions during the lifetime of the Holy Prophet (Sallallaho alaihe wasallam). He said to me, “Ma’athallaah! During those blessed days, whenever the wind blew strong, we would hurry to the musjid lest it should be the approach of the Last Day.”", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0180000-0000-4000-8000-000000000004", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abdullah bin Salaam (Radhiyallaho anho) narrates that whenever the members of the Prophet''s family were hardpressed in any way, the Prophet (Sallallaho alaihe wasallam) would enjoin upon them to say salaat, and would recite the following verse of the Holy Qur''an:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0180000-0000-4000-8000-000000000005", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 5, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَأْمُرْ أَهْلَكَ بِالصَّلَاةِ وَاصْطَبِرْ عَلَيْهَا لَا نَسْأَلُكَ رِزْقًا نَحْنُ نَرْزُقُكَ وَالْعَاقِبَةُ لِلتَّقْوَى", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}], "pageNumber": 18}'::jsonb);
